steps.fn:
() => {
 const data = JSON.parse(document.body.innerText);
 if (!Array.isArray(data.docs)) throw new Error('Open Library 未返回有效书目，检查当前页面');
 return {total: data.numFound, books: data.docs.map(b => ({title: b.title, authors: b.author_name || [], firstPublishYear: b.first_publish_year, editionCount: b.edition_count, isbn: (b.isbn || []).slice(0,5), url: 'https://openlibrary.org' + b.key}))};
}
